/* Shared test tools: calculator, history, formula sheet, drawing pad, image zoom.
   To use in any practice test page, add a script tag with src="tools.js" at the end of the body.
   Test pages can call zoomImg(src) to open the zoom viewer. */
(function(){
const FS=["data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const st=document.createElement('style');st.textContent="#tb{position:fixed;right:14px;bottom:calc(14px + env(safe-area-inset-bottom,0px));z-index:20;background:var(--pri);color:var(--priTx);border-color:var(--pri);font-weight:700;border-radius:99px;padding:12px 18px;box-shadow:0 4px 14px rgba(0,0,0,.25)}\n#tp{position:fixed;right:14px;bottom:calc(70px + env(safe-area-inset-bottom,0px));z-index:20;width:min(360px,calc(100vw - 28px));max-height:calc(100vh - 120px);overflow:auto;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px;box-shadow:0 8px 28px rgba(0,0,0,.3);display:none}\n#tp.on{display:block}\n.tabs{display:flex;gap:6px;margin-bottom:10px}\n.tabs button{flex:1;text-align:center;padding:8px 2px;font-size:.78rem}\n.tabs button.on{background:var(--pri);color:var(--priTx);border-color:var(--pri)}\n.disp{width:100%;font:inherit;font-size:1.2rem;text-align:right;padding:10px;border-radius:10px;border:1px solid var(--line);background:var(--bg);color:var(--tx)}\n.res{text-align:right;font-size:1.5rem;font-weight:700;min-height:2.2rem;padding:4px 4px 8px;word-break:break-all}\n.keys{display:grid;grid-template-columns:repeat(5,1fr);gap:6px}\n.keys button{text-align:center;padding:10px 0;font-size:1rem}\n.keys button.op{background:var(--ex)}\n.keys button.eq{background:var(--pri);color:var(--priTx);border-color:var(--pri);font-weight:700}\n#sp{width:100%;height:260px;resize:vertical;font:inherit;padding:10px;border-radius:10px;border:1px solid var(--line);background:var(--bg);color:var(--tx)}\n.fs h4{margin:10px 0 4px;font-size:.95rem}\n.fs h4:first-child{margin-top:0}\n.fs p{margin:2px 0;font-size:.9rem}\n.hist{display:grid;gap:6px}\n.hist button{display:flex;justify-content:space-between;gap:10px;text-align:left;padding:8px 10px}\n.hist span{word-break:break-all;color:var(--mut)}\n.hist b{white-space:nowrap}\n.dt{display:flex;gap:6px;align-items:center;flex-wrap:wrap}\n.dt button{padding:6px 10px;text-align:center}\n.dt button.on{background:var(--pri);color:var(--priTx);border-color:var(--pri)}\n.dt button[data-d^='#']{width:28px;height:28px;padding:0;border-radius:50%}\n.dt button.sel{outline:3px solid var(--pri);outline-offset:2px}\n.dt input{flex:1;min-width:60px}\n#cv{width:100%;height:auto;touch-action:none;background:#fff;border:1px solid var(--line);border-radius:10px;display:block;margin-top:8px;cursor:crosshair}\n.fs img{width:100%;height:auto;display:block;border:1px solid var(--line);border-radius:8px;background:#fff;margin-bottom:8px;cursor:zoom-in}\n.zrow{display:flex;justify-content:flex-end;margin-bottom:8px}\n.zbtn{padding:6px 12px;font-size:.9rem}\n.qimg img{cursor:zoom-in}\n#zo{position:fixed;inset:0;z-index:50;background:rgba(0,0,0,.88);display:flex;flex-direction:column;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}\n#zo .zbar{display:flex;gap:8px;align-items:center;justify-content:center;padding:10px;color:#fff;flex-wrap:wrap}\n#zo .zbar button{padding:8px 14px;text-align:center}\n#zo .zw{flex:1;overflow:auto;-webkit-overflow-scrolling:touch;padding:10px}\n#zo .zw img{display:block;margin:0 auto;max-width:none;background:#fff;border-radius:6px}\n";document.head.appendChild(st);
const casio=document.createElement('style');casio.textContent=`
#tp.casio{width:min(410px,calc(100vw - 28px))!important;background:#d9dce0;color:#18202a;border:2px solid #777;border-radius:18px;padding:12px;box-shadow:0 10px 30px #0005}
#tp.casio .tabs{gap:5px}#tp.casio .tabs button{background:#c4c8cd;color:#17202a;border:1px solid #89919a;border-radius:7px;font-weight:700}
#tp.casio .tabs button.on{background:#525b66;color:white}
#tp.casio .screen{background:#dce8d4;border:2px solid #7d8874;border-radius:7px;padding:7px 10px;margin:5px 0 11px;box-shadow:inset 0 1px 5px #0002}
#tp.casio .status{font:700 10px/1.4 Arial,sans-serif;color:#52604d;letter-spacing:1px;display:flex;justify-content:space-between}
#tp.casio .disp{border:0;background:transparent;color:#172319;border-radius:0;font:18px 'Courier New',monospace;text-align:right;padding:8px 0 2px;min-height:35px;box-shadow:none}
#tp.casio .res{font:22px 'Courier New',monospace;color:#172319;min-height:32px;padding:3px 0;text-align:right}
#tp.casio .keys{grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}
#tp.casio .keys button{min-height:39px;padding:5px 1px;border:1px solid #a2a8af;border-radius:7px;background:linear-gradient(#fff,#e5e7e9);color:#17202a;font:600 13px Arial,sans-serif;box-shadow:0 2px 0 #9da3aa}
#tp.casio .keys button.op{background:linear-gradient(#626b76,#444d58);color:#fff;border-color:#3f4852}
#tp.casio .keys button.eq{background:linear-gradient(#f5a62d,#df8312);color:#171717;border-color:#bd710e}
#tp.casio .keys button.fn{font-size:11px;background:linear-gradient(#d4d8dc,#b9bec4)}
#tp.casio .hint{color:#27313a}
#tp.casio .calc-note{font:10px Arial;color:#46515b;text-align:center;margin-top:9px}
@media(max-width:390px){#tp.casio .keys{gap:5px}#tp.casio .keys button{min-height:36px;font-size:12px}}
`;document.head.appendChild(casio);

const tb=document.createElement('button');tb.id='tb';tb.textContent='\uD83E\uDDEE Tools';const tpd=document.createElement('div');tpd.id='tp';document.body.append(tb,tpd);
const esc=s=>String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const TP=document.getElementById('tp'),TB=document.getElementById('tb');
let tab='calc',deg=true,expr='',res='',ansv=0,lastVal=null,showFrac=false,padImg='',undo=[],pen={c:'#111',w:3,erase:false},hist=[];
try{hist=JSON.parse(localStorage.getItem('eqh')||'[]')}catch(e){}
const hsave=()=>{try{localStorage.setItem('eqh',JSON.stringify(hist))}catch(e){}};
function fracStr(x){if(!isFinite(x))return null;const ng=x<0;let v=Math.abs(x);if(Number.isInteger(parseFloat(v.toPrecision(12))))return String((ng?-1:1)*Math.round(v));let h1=1,h2=0,k1=0,k2=1,b=v;for(let n=0;n<30;n++){const a=Math.floor(b),h=a*h1+h2,k=a*k1+k2;h2=h1;h1=h;k2=k1;k1=k;if(k>10000)return null;if(Math.abs(v-h/k)<1e-9*Math.max(1,v)){const s=ng?'-':'',w=Math.floor(h/k),r=h%k;return s+h+'/'+k+(w>0&&r>0?' ('+s+w+' '+r+'/'+k+')':'')}if(b-a<1e-12)return null;b=1/(b-a)}return null}
function wireHist(){TP.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{const x=hist[+b.dataset.h];expr=x.e;res=x.r;tab='calc';tools()});const c=document.getElementById('hclr');if(c)c.onclick=()=>{hist=[];hsave();tools()}}
function initDraw(){
 const cv=document.getElementById('cv'),x=cv.getContext('2d');
 const paint=src=>{x.fillStyle='#fff';x.fillRect(0,0,cv.width,cv.height);if(src){const im=new Image();im.onload=()=>x.drawImage(im,0,0);im.src=src}};
 paint(padImg);
 let down=false,lx=0,ly=0;
 const pos=e=>{const r=cv.getBoundingClientRect();return[(e.clientX-r.left)*cv.width/r.width,(e.clientY-r.top)*cv.height/r.height]};
 const seg=(a,b,c,d)=>{x.lineCap='round';x.lineJoin='round';x.strokeStyle=pen.erase?'#fff':pen.c;x.lineWidth=(pen.erase?pen.w*4:pen.w)*2;x.beginPath();x.moveTo(a,b);x.lineTo(c,d);x.stroke()};
 cv.onpointerdown=e=>{e.preventDefault();cv.setPointerCapture(e.pointerId);down=true;undo.push(cv.toDataURL());if(undo.length>20)undo.shift();[lx,ly]=pos(e);seg(lx,ly,lx+0.1,ly)};
 cv.onpointermove=e=>{if(!down)return;const[p,q]=pos(e);seg(lx,ly,p,q);lx=p;ly=q};
 cv.onpointerup=cv.onpointercancel=()=>{down=false};
 const pw=document.getElementById('pw');pw.oninput=()=>{pen.w=+pw.value};
 TP.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{const v=b.dataset.d;
  if(v==='undo'){const s=undo.pop();if(s)paint(s);return}
  if(v==='clr'){undo.push(cv.toDataURL());paint(null);return}
  if(v==='pen')pen.erase=false;else if(v==='er')pen.erase=true;else{pen.c=v;pen.erase=false}
  tools()})}
const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
TB.onclick=()=>{TP.classList.toggle('on');if(TP.classList.contains('on'))tools()};
const fm=v=>{if(!isFinite(v))throw 0;if(Math.abs(v)<1e-12)v=0;return String(parseFloat(v.toPrecision(10)))};
function evalx(s){
 s=s.replace(/×/g,'*').replace(/÷/g,'/').replace(/[−–]/g,'-').replace(/π/g,'pi').replace(/√/g,'sqrt').replace(/\s+/g,'').toLowerCase();
 const raw=s.match(/\d*\.\d+|\d+\.?|[a-z]+|[-+*\/^()!]/g)||[];
 if(raw.join('')!==s)throw 0;
 const R=x=>deg?x*Math.PI/180:x,D=x=>deg?x*180/Math.PI:x;
 const F={sin:x=>Math.sin(R(x)),cos:x=>Math.cos(R(x)),tan:x=>Math.tan(R(x)),asin:x=>D(Math.asin(x)),acos:x=>D(Math.acos(x)),atan:x=>D(Math.atan(x)),sinh:Math.sinh,cosh:Math.cosh,tanh:Math.tanh,asinh:Math.asinh,acosh:Math.acosh,atanh:Math.atanh,sqrt:Math.sqrt,ln:Math.log,log:Math.log10,abs:Math.abs,exp:Math.exp,floor:Math.floor,ceil:Math.ceil};
 const C={pi:Math.PI,e:Math.E,ans:ansv};
 const t=[];
 raw.forEach(k=>{const p=t[t.length-1];const isv=x=>x!==undefined&&(/^[\d.]/.test(x)||own(C,x));const nv=isv(k)||own(F,k)||k==='(';if(nv&&(isv(p)||p===')'))t.push('*');t.push(k)});
 let i=0;const pk=()=>t[i],nx=()=>t[i++];
 function ex(){let v=tm();while(pk()==='+'||pk()==='-'){const o=nx(),r=tm();v=o==='+'?v+r:v-r}return v}
 function tm(){let v=un();while(pk()==='*'||pk()==='/'){const o=nx(),r=un();v=o==='*'?v*r:v/r}return v}
 function un(){if(pk()==='-'){nx();return -un()}if(pk()==='+'){nx();return un()}return pw()}
 function pw(){let b=at();while(pk()==='!'){nx();if(b<0||!Number.isInteger(b)||b>170)throw 0;let z=1;for(let q=2;q<=b;q++)z*=q;b=z}if(pk()==='^'){nx();return Math.pow(b,un())}return b}
 function at(){const k=nx();if(k===undefined)throw 0;
  if(k==='('){const v=ex();if(pk()===')')nx();return v}
  if(own(F,k)){if(nx()!=='(')throw 0;const v=ex();if(pk()===')')nx();return F[k](v)}
  if(own(C,k))return C[k];
  const n=parseFloat(k);if(isNaN(n))throw 0;return n}
 const v=ex();if(i<t.length)throw 0;return v}
function press(a){
 const d=document.getElementById('dsp'),r=document.getElementById('res');
 if(a==='mode'){deg=!deg;tools();return}
 if(a==='frac'){if(lastVal==null)return;showFrac=!showFrac;res=showFrac?(fracStr(lastVal)||'No simple fraction'):fm(lastVal);r.textContent=res;return}
 if(a==='eq'){try{const v=evalx(d.value);ansv=v;lastVal=v;showFrac=false;res=fm(v);hist.unshift({e:d.value,r:res});if(hist.length>40)hist.pop();hsave()}catch(e){res='Error';lastVal=null}r.textContent=res;return}
 if(a==='clr'){d.value='';res='';r.textContent='';expr='';return}
 let s=d.selectionStart,e=d.selectionEnd;if(s==null){s=e=d.value.length}
 const v=d.value;
 if(a==='bs'){if(s===e&&s>0)s--;d.value=v.slice(0,s)+v.slice(e);d.setSelectionRange(s,s);expr=d.value;return}
 d.value=v.slice(0,s)+a+v.slice(e);d.setSelectionRange(s+a.length,s+a.length);expr=d.value}
function tools(){
 const od=document.getElementById('dsp');if(od)expr=od.value;
 const oc=document.getElementById('cv');if(oc)padImg=oc.toDataURL();
 const T=[['calc','Calc'],['hi','History'],['fs','Formulas'],['dr','Draw']];
 let h=`<div class='tabs'>${T.map(a=>`<button data-t='${a[0]}' class='${tab===a[0]?'on':''}'>${a[1]}</button>`).join('')}</div>`;
 TP.classList.remove('casio');
 if(tab==='calc'){
  TP.classList.add('casio');
  const K=[['DEG/RAD','mode','fn'],['Ans','ans','op'],['π','π','op'],['e','e','op'],['AC','clr','fn'],
  ['sin','sin(','op'],['cos','cos(','op'],['tan','tan(','op'],['sin⁻¹','asin(','fn'],['cos⁻¹','acos(','fn'],
  ['tan⁻¹','atan(','fn'],['sinh','sinh(','fn'],['cosh','cosh(','fn'],['tanh','tanh(','fn'],['!','!','op'],
  ['x²','^2','op'],['x³','^3','op'],['^','^','op'],['√','√(','op'],['x⁻¹','^(-1)','op'],
  ['log','log(','op'],['ln','ln(','op'],['10ˣ','10^(','op'],['eˣ','exp(','op'],['⌫','bs','op'],
  ['a b/c','frac','op'],['(','(','op'],[')',')','op'],['S⇔D','frac','op'],['AC','clr','op']
  ['7','7'],['8','8'],['9','9'],['×','×','op'],['÷','÷','op'],
  ['4','4'],['5','5'],['6','6'],['+','+','op'],['−','-','op'],
  ['1','1'],['2','2'],['3','3'],['π','π','op'],['e','e','op'],
  ['0','0'],['.','.'],['×10ˣ','*10^(','op'],['EXP','*10^(','op'],['=','eq','eq']];
  h+=`<div class='screen'><div class='status'><span>${deg?'D':'R'}   M   Math</span><span>CASIO fx-300ES style</span></div><input id='dsp' class='disp' inputmode='none' autocomplete='off' spellcheck='false' placeholder='0'><div class='res' id='res'>${esc(res)}</div></div><div class='keys'>${K.map(k=>`<button data-a='${k[1]}' class='${k[2]||''}'>${esc(k[0])}</button>`).join('')}</div><div class='calc-note'>Scientific calculator • ${deg?'DEG':'RAD'} mode</div>`;
 }else if(tab==='fs'){
  h+=`<div class='fs'>${FS.map((s,k)=>`<img src='${s}' data-zi='${k}' alt='Formula sheet page ${k+1}'>`).join('')}<p class='hint'>Tap a page to zoom in.</p></div>`;
 }else if(tab==='hi'){
  h+=hist.length?`<div class='hist'>${hist.map((x,j)=>`<button data-h='${j}'><span>${esc(x.e)}</span><b>= ${esc(x.r)}</b></button>`).join('')}</div><div class='act'><button id='hclr'>Clear history</button></div>`:`<p class='hint'>Nothing yet. Your answers show up here after you press =.</p>`;
 }else{
  h+=`<div class='dt'><button data-d='pen' class='${pen.erase?'':'on'}'>Pen</button><button data-d='er' class='${pen.erase?'on':''}'>Eraser</button>${['#111','#1c4fd8','#d62828'].map(c=>`<button data-d='${c}' class='${!pen.erase&&pen.c===c?'sel':''}' style='background:${c}'></button>`).join('')}<input type='range' id='pw' min='1' max='10' value='${pen.w}'><button data-d='undo'>Undo</button><button data-d='clr'>Clear</button></div><canvas id='cv' width='992' height='800'></canvas>`}
 TP.innerHTML=h;
 TP.querySelectorAll('[data-zi]').forEach(im=>im.onclick=()=>zoomImg(im.src));
 TP.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{tab=b.dataset.t;tools()});
 const d=document.getElementById('dsp');
 if(d){d.value=expr;d.oninput=()=>{expr=d.value};d.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();press('eq')}};TP.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>press(b.dataset.a))}
 TP.style.width=(tab==='dr'||tab==='fs')?'min(520px,calc(100vw - 28px))':'';if(tab==='dr')initDraw();if(tab==='hi')wireHist()}

function zoomImg(src){
 if(document.getElementById('zo'))return;
 const o=document.createElement('div');o.id='zo';
 o.innerHTML=`<div class='zbar'><button data-z='-'>\u2212</button><span id='zl'>100%</span><button data-z='+'>+</button><button data-z='0'>Fit</button><button data-z='x'>Close</button></div><div class='zw'></div>`;
 const im=new Image();im.src=src;im.alt='Zoomed image';
 o.querySelector('.zw').appendChild(im);document.body.appendChild(o);
 let z=100;const set=v=>{z=Math.max(50,Math.min(500,v));im.style.width=z+'%';o.querySelector('#zl').textContent=z+'%'};set(100);
 const kd=e=>{if(e.key==='Escape')close();else if(e.key==='+'||e.key==='=')set(z+25);else if(e.key==='-')set(z-25)};
 const close=()=>{o.remove();document.removeEventListener('keydown',kd)};
 document.addEventListener('keydown',kd);
 o.querySelectorAll('[data-z]').forEach(b=>b.onclick=()=>{const k=b.dataset.z;if(k==='x')close();else if(k==='0')set(100);else set(z+(k==='+'?25:-25))});
 im.ondblclick=()=>set(z>100?100:250);
}
window.zoomImg=zoomImg;
})();
